css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; animation: cycle calc(var(--loader-speed) * 1.9) cubic-bezier(.6, 0, .3, 1) infinite; }
.loader span { position: absolute; inset: 0; border-radius: 50%; border: calc(var(--loader-size) * .1) solid transparent; }
.loader span:nth-child(1) { border-top-color: var(--accent); border-right-color: var(--accent); }
.loader span:nth-child(2) { border-bottom-color: var(--accent-2); border-left-color: var(--accent-2); }
.loader span::after { content: ''; position: absolute; width: 46%; height: 30%; }
.loader span:nth-child(1)::after { top: 34%; right: -30%; clip-path: polygon(0 0, 100% 0, 50% 100%); background: var(--accent); }
.loader span:nth-child(2)::after { bottom: 34%; left: -30%; clip-path: polygon(50% 0, 100% 100%, 0 100%); background: var(--accent-2); }
@keyframes cycle { 0% { transform: rotate(0deg); } 44% { transform: rotate(196deg); } 56% { transform: rotate(196deg); } 100% { transform: rotate(360deg); } }
